diff --git a/src/TaskTracker.Api/Endpoints/TaskEndpoints.cs b/src/TaskTracker.Api/Endpoints/TaskEndpoints.cs
index 74842c8..3faf2a4 100644
--- a/src/TaskTracker.Api/Endpoints/TaskEndpoints.cs
+++ b/src/TaskTracker.Api/Endpoints/TaskEndpoints.cs
@@ -7,9 +7,9 @@ namespace TaskTracker.Api.Endpoints;
 /// CRUD endpoints for tasks, mounted under <c>/tasks</c>.
 /// </summary>
 /// <remarks>
-/// GET /tasks currently returns EVERY task, unfiltered. Closing that gap â€” adding optional
-/// <c>?status=</c> and <c>?priority=</c> filters â€” is the exercise the CHAOS worked example
-/// drives end-to-end. See <c>docs/demo/README.md</c>.
+/// GET /tasks takes an optional <c>?priority=</c> filter (add-priority-filter). The matching
+/// <c>?status=</c> filter, and the two combined with AND, are still open â€” see
+/// <c>docs/demo/README.md</c>.
 /// </remarks>
 public static class TaskEndpoints
 {
@@ -21,8 +21,28 @@ public static class TaskEndpoints
             .RequireAuthorization()
             .RequireRateLimiting(Policies.TaskRateLimit);

-        // GET /tasks â€” returns every task in the store. No filtering (yet).
-        group.MapGet("/", (TaskStore store) => Results.Ok(store.All()));
+        // GET /tasks â€” every task in the store, optionally narrowed by ?priority=.
+        // The parameter is bound as a raw string rather than as TaskPriority? on purpose: the
+        // framework's enum binding delegates to Enum.TryParse, which also accepts numeric values
+        // ("0") and comma-separated lists ("Low,High"), so ?priority=Low,High would quietly
+        // return the Low tasks with a 200 instead of the 400 the contract requires.
+        group.MapGet("/", (string? priority, TaskStore store) =>
+        {
+            var tasks = store.All();
+
+            // Absent parameter = no filter. A present-but-empty ?priority= is a supplied value
+            // like any other, and so fails the check below rather than returning everything.
+            if (priority is null)
+                return Results.Ok(tasks);
+
+            if (!TryParsePriority(priority, out var requested))
+                return Results.BadRequest(new
+                {
+                    error = $"Unknown priority '{priority}'. Expected one of: Low, Medium, High."
+                });
+
+            return Results.Ok(tasks.Where(t => t.Priority == requested).ToList());
+        });

         // GET /tasks/{id}
         group.MapGet("/{id:guid}", (Guid id, TaskStore store) =>
@@ -55,4 +75,24 @@ public static class TaskEndpoints

         return app;
     }
+
+    /// <summary>
+    /// Matches a query value against the <see cref="TaskPriority"/> names, case-insensitively
+    /// (`low` and `Low` are the same value, as they already are in a request body) but exactly:
+    /// only a whole name matches, so lists, numeric values and the empty string are rejected.
+    /// </summary>
+    private static bool TryParsePriority(string value, out TaskPriority priority)
+    {
+        foreach (var name in Enum.GetNames<TaskPriority>())
+        {
+            if (string.Equals(name, value, StringComparison.OrdinalIgnoreCase))
+            {
+                priority = Enum.Parse<TaskPriority>(name);
+                return true;
+            }
+        }
+
+        priority = default;
+        return false;
+    }
 }
diff --git a/tests/TaskTracker.Tests/TaskEndpointsTests.cs b/tests/TaskTracker.Tests/TaskEndpointsTests.cs
index 6c4eb37..ea8bf56 100644
--- a/tests/TaskTracker.Tests/TaskEndpointsTests.cs
+++ b/tests/TaskTracker.Tests/TaskEndpointsTests.cs
@@ -90,6 +90,103 @@ public class TaskEndpointsTests : IClassFixture<TestApiFactory>
         Assert.Equal(HttpStatusCode.BadRequest, response.StatusCode);
     }

+    // ---- ?priority= filter (add-priority-filter) ----
+
+    [Fact]
+    public async Task Get_tasks_without_priority_returns_every_priority()
+    {
+        var client = _factory.CreateAuthenticatedClient();
+
+        var all = await client.GetFromJsonAsync<List<TaskDto>>("/tasks");
+        var low = await client.GetFromJsonAsync<List<TaskDto>>("/tasks?priority=Low");
+        var medium = await client.GetFromJsonAsync<List<TaskDto>>("/tasks?priority=Medium");
+        var high = await client.GetFromJsonAsync<List<TaskDto>>("/tasks?priority=High");
+
+        // The unfiltered list is exactly the three filtered lists put together: adding the
+        // filter did not start hiding anything from the default response.
+        Assert.Equal(all!.Count, low!.Count + medium!.Count + high!.Count);
+    }
+
+    [Fact]
+    public async Task Get_tasks_filtered_by_priority_returns_only_that_priority()
+    {
+        var client = _factory.CreateAuthenticatedClient();
+
+        var response = await client.GetAsync("/tasks?priority=High");
+        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
+
+        var tasks = await response.Content.ReadFromJsonAsync<List<TaskDto>>();
+        Assert.NotEmpty(tasks!);
+        Assert.All(tasks!, t => Assert.Equal("High", t.Priority));
+        Assert.Contains(tasks!, t => t.Title == "Add query-param filters to GET /tasks");
+    }
+
+    [Theory]
+    [InlineData("low")]
+    [InlineData("LOW")]
+    [InlineData("Low")]
+    public async Task Get_tasks_priority_filter_ignores_casing(string value)
+    {
+        var client = _factory.CreateAuthenticatedClient();
+
+        var canonical = await client.GetFromJsonAsync<List<TaskDto>>("/tasks?priority=Low");
+        var variant = await client.GetFromJsonAsync<List<TaskDto>>($"/tasks?priority={value}");
+
+        Assert.Equal(
+            canonical!.Select(t => t.Id).OrderBy(id => id),
+            variant!.Select(t => t.Id).OrderBy(id => id));
+    }
+
+    [Fact]
+    public async Task Get_tasks_filter_matching_nothing_returns_an_empty_list()
+    {
+        // A dedicated app instance: the store is a singleton, so emptying a priority here
+        // must not disturb the seeded data the other tests in this class rely on.
+        using var factory = TestApiFactory.With(new Dictionary<string, string?>());
+        var client = factory.CreateAuthenticatedClient();
+
+        foreach (var task in await client.GetFromJsonAsync<List<TaskDto>>("/tasks?priority=Low") ?? [])
+        {
+            await client.DeleteAsync($"/tasks/{task.Id}");
+        }
+
+        var response = await client.GetAsync("/tasks?priority=Low");
+
+        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
+        Assert.Empty((await response.Content.ReadFromJsonAsync<List<TaskDto>>())!);
+    }
+
+    [Theory]
+    [InlineData("Urgent")]      // not one of the three names
+    [InlineData("Low,High")]    // a list: Enum.TryParse would accept this and return the Low tasks
+    [InlineData("0")]           // a numeric enum value: Enum.TryParse would accept this too
+    [InlineData("2")]
+    [InlineData("")]            // present but empty - a supplied value, not an omitted parameter
+    [InlineData("  ")]
+    public async Task Get_tasks_with_an_unrecognised_priority_is_rejected(string value)
+    {
+        var client = _factory.CreateAuthenticatedClient();
+
+        var response = await client.GetAsync($"/tasks?priority={Uri.EscapeDataString(value)}");
+
+        Assert.Equal(HttpStatusCode.BadRequest, response.StatusCode);
+
+        // A rejection carries an error, never task data.
+        var body = await response.Content.ReadAsStringAsync();
+        Assert.Contains("error", body, StringComparison.OrdinalIgnoreCase);
+        Assert.DoesNotContain("createdAt", body, StringComparison.OrdinalIgnoreCase);
+    }
+
+    [Fact]
+    public async Task Get_tasks_with_a_priority_filter_still_requires_authentication()
+    {
+        var client = _factory.CreateClient();
+
+        var response = await client.GetAsync("/tasks?priority=High");
+
+        Assert.Equal(HttpStatusCode.Unauthorized, response.StatusCode);
+    }
+
     /// <summary>Mirror of the API's task shape; enums arrive as strings ("Open", "High").</summary>
     internal record TaskDto(Guid Id, string Title, string Status, string Priority, DateTimeOffset CreatedAt);
 }
